CREATE TABLE IF NOT EXISTS "account_token_health" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "token_id" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'unknown', "last_success_at" TEXT, "last_failure_at" TEXT, "last_probe_at" TEXT, "last_probe_model" TEXT, "last_used_model" TEXT, "last_error" TEXT, "failure_count" INTEGER NOT NULL DEFAULT 0, "next_probe_at" TEXT, "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("token_id") REFERENCES "account_tokens"("id") ON DELETE CASCADE);
ALTER TABLE "account_tokens" ADD COLUMN "probe_model" TEXT;
ALTER TABLE "sites" ADD COLUMN "token_health_probe_model" TEXT;
CREATE UNIQUE INDEX "account_token_health_token_unique" ON "account_token_health" ("token_id");
CREATE INDEX "account_token_health_next_probe_idx" ON "account_token_health" ("next_probe_at");
CREATE INDEX "account_token_health_status_idx" ON "account_token_health" ("status");
